<section class="card daily-progress" aria-labelledby="daily-progress-title">
<div class="section-heading"><div><h2 id="daily-progress-title">Your daily progress</h2><p class="muted">See what you recorded, one day at a time.</p></div><form method="get" action="/" class="day-picker inline"><label class="sr-only" for="progress-date">Review a day</label><input id="progress-date" type="date" name="date" max="<?= e(date('Y-m-d')) ?>" value="<?= e($selectedDay) ?>" data-date-suggestions="off" required><button class="secondary">Show day</button></form></div>
<nav class="day-links" aria-label="Review day"><a href="/?date=<?= e(date('Y-m-d',strtotime($selectedDay.' -1 day'))) ?>">← Previous day</a><?php if ($selectedDay!==date('Y-m-d')): ?><a href="/">Today</a><a href="/?date=<?= e(date('Y-m-d',strtotime($selectedDay.' +1 day'))) ?>">Next day →</a><?php else: ?><span class="muted">Today · <?= e(date('D, j M',strtotime($selectedDay))) ?></span><?php endif; ?></nav>
<?php if ($dailyProgress['has_activity']): ?><dl class="daily-metrics"><div><dt>Tasks completed</dt><dd><?= e($dailyProgress['tasks']) ?></dd></div><div><dt>Study time</dt><dd><?= e($dailyProgress['focus_minutes']) ?><small>minutes</small></dd></div><div><dt>Time for yourself</dt><dd><?= e($dailyProgress['personal_minutes']) ?><small>minutes</small></dd></div><div><dt>Spending</dt><dd><?= money($dailyProgress['expenses']) ?></dd></div></dl><?php endif; ?>
<?php if (!$dailyProgress['has_activity']): ?><p class="muted">No activity recorded for this day. Add an expense, finish a task, or <a href="/freedom#personal-time">log some personal time</a>.</p><?php else: ?><p class="daily-extra"><?= e($dailyProgress['goal_steps']) ?> goal steps completed · <?= e($dailyProgress['habits']) ?> habit check-ins · <?= e($dailyProgress['expense_count']) ?> expense entries<?php if ($dailyProgress['income_count']): ?> ? Income recorded <?= money($dailyProgress['income']) ?><?php endif; ?></p><?php endif; ?>
<details class="progress-history"><summary>View your last 7 days <span class="muted">Study, personal time and completed actions</span></summary><div class="table-wrap"><table><thead><tr><th>Day</th><th>Tasks</th><th>Goal steps</th><th>Study</th><th>Personal time</th><th>Spending</th></tr></thead><tbody><?php foreach (array_reverse($dailyHistory) as $day): ?><tr><td><a href="/?date=<?= e($day['date']) ?>"><?= e(date('D, j M',strtotime($day['date']))) ?></a></td><td><?= e($day['tasks']) ?></td><td><?= e($day['goal_steps']) ?></td><td><?= e($day['focus_minutes']) ?> min</td><td><?= e($day['personal_minutes']) ?> min</td><td><?= money($day['expenses']) ?></td></tr><?php endforeach; ?></tbody></table></div><p class="footnote">Completion dates are recorded from this update onward; older undated completions stay unknown. Study minutes use the day a session was completed.</p></details>
</section>
<?php if ($suggestions): ?><section class="next-dates" aria-label="Suggested next actions from saved dates"><?php foreach ($suggestions as $item): ?><a href="<?= e($item['route']) ?>"><span class="next-date-label <?= $item['when']==='Overdue' ? 'error-text' : '' ?>"><?= e($item['when']) ?> · <?= e($item['kind']) ?></span><strong><?= e($item['title']) ?></strong><span aria-hidden="true">→</span></a><?php endforeach; ?></section><?php endif; ?>
